/// <summary>
/// This class is extension of Markup class and was brought in to address CB326: auto charges header shrink wrap
/// </summary>
[ExtensionOf(classStr(Markup))]
final class METMarkup_Extension
{
}

Method.Source:
    /// <summary>
    /// COC method that Returns the calculated miscellaneous charges amount for an miscellaneous charges transaction based Charges Method for Shrink wrap.
    /// </summary>
    /// <param name="_markupTrans">
    ///    The miscellaneous charges transaction to calculate miscellaneous charges amount from.
    /// </param>
    /// <param name = "_refReturnInvoiceTrans_W">
    ///     An instance of <c>RefReturnInvoiceTrans_W</c> class.
    /// </param>
    /// <param name="_qty">
    ///    The quantity to calculate miscellaneous charges amount from.
    /// </param>
    /// <param name="_value">
    ///    The value to calculate miscellaneous charges amount from.
    /// </param>
    /// <param name="_interCompanyValue">
    ///    The intercompany value to calculate miscellaneous charges amount from; optional.
    /// </param>
    /// <param name="_transDate">
    ///    The date that is used to convert miscellaneous charges from one currency to another currency;
    ///    optional.
    /// </param>
    /// <param name="_absoluteValue">
    ///     The absolute value of the related markup transaction.
    /// </param>
    /// <param name="_parmId">
    ///     The ID for the relating markup transaction.
    /// </param>
    /// <param name="_mcrPostingInvoice">
    ///     The posting invoice record of the related markup transaction.
    /// </param>
    /// <param name="_isInterCompanyMarkup">
    ///     Boolean value, states if calculation is performed for intercompany purchase order; optional.
    /// </param>
    /// <returns>
    ///    The calculated miscellaneous charges amount.
    /// </returns>
    protected static MarkupAmount getMarkupAmountFromMarkupCategory(MarkupTrans             _markupTrans,
                                                                    RefReturnInvoiceTrans_W _refReturnInvoiceTrans_W,
                                                                    Qty                     _qty,
                                                                    AmountCur               _value,
                                                                    AmountCur               _interCompanyValue,
                                                                    TransDate               _transDate,
                                                                    AmountCur               _absoluteValue,
                                                                    ParmId                  _parmId,
                                                                    boolean                 _mcrPostingInvoice,
                                                                    boolean                 _isInterCompanyMarkup)
    {
        MarkupAmount    markupAmount;
        Weight          totalWeight;
        Volume          totalVolume;

        markupAmount = next getMarkupAmountFromMarkupCategory(_markupTrans, _refReturnInvoiceTrans_W, _qty, _value,
                                                              _interCompanyValue, _transDate, _absoluteValue, _parmId,
                                                              _mcrPostingInvoice, _isInterCompanyMarkup);

        //The calculation must takes place only for Sales Order header and when the applied Auto charge is enabled for Advanced calculation
        if (_markupTrans.TransTableId == tableNum(SalesTable) && _markupTrans.METAdvancedCalculation && _markupTrans.METChargesMethod != METChargesMethod::NotApplicable)
        {
            CurrencyCode parentCurrencyCode = _markupTrans.parentCurrencyCode();
            SalesTable salesTable = SalesTable::findRecId(_markupTrans.TransRecId);
            [totalWeight, totalVolume]   = Markup::METGetTotalWeightAndVolume(salesTable.SalesId);
            switch(_markupTrans.METChargesMethod)
            {
                //If charges method on the Markup transaction is set for Weight, then, Markup value is multiplied with total weight (With out of the Box Currency conversion procedure) avoiding Category calculation)
                case METChargesMethod::Weight:
                    markupAmount = CurrencyExchangeHelper::amount(_markupTrans.Value * totalWeight, parentCurrencyCode);
                    break;
                //If charges method on the Markup transaction is set for Volume, then, Markup value is multiplied with total Volume (With out of the Box Currency conversion procedure) avoiding Category calculation)
                case METChargesMethod::Volume:
                    markupAmount = CurrencyExchangeHelper::amount(_markupTrans.Value * totalVolume, parentCurrencyCode);
                    break;
                case METChargesMethod::Pallet:
                    markupAmount = CurrencyExchangeHelper::amount(_markupTrans.Value * Markup::METGetTotalContainerQty(salesTable.SalesId, METWHSContainerChargesMethod::ShrinkWrap), parentCurrencyCode);
                    break;
                case METChargesMethod::SecurityCap:
                    markupAmount = CurrencyExchangeHelper::amount(_markupTrans.Value * Markup::METGetTotalContainerQty(salesTable.SalesId, METWHSContainerChargesMethod::SecurityCap), parentCurrencyCode);
                    break;
            }

        }

        return markupAmount;
    }

    /// <summary>
    /// CB326, Bug:84962, returns total weight and total volume for a sales id
    /// </summary>
    /// <param name = "_salesId">SalesId</param>
    /// <returns>Container</returns>
    static container METdeliveredWeightAndVolume(SalesId   _salesId)
    {
        Volume                  totalVolume;
        Weight                  totalWeight;
        SalesLine               salesLine;
        InventTable             inventTable;
        custPackingSlipTrans    custPackingSlipTrans;

        while select ItemId, InventTransId from salesLine
            where salesLine.SalesId == _salesId
        {
            inventTable = salesLine.inventTable();
            select sum(InventQty)
            from custPackingSlipTrans
            where custPackingSlipTrans.InventTransId == salesLine.InventTransId;
            totalWeight += custPackingSlipTrans.InventQty * inventTable.grossWeight();
            totalVolume += custPackingSlipTrans.InventQty * inventTable.UnitVolume;
        }

        return [totalWeight, totalVolume];
    }

    /// <summary>
    /// CB326 returns total weight and total volume for a sales id
    /// </summary>
    /// <param name = "_salesId">SalesId</param>
    /// <returns>Container</returns>
    static container METGetTotalWeightAndVolume(SalesId   _salesId)
    {
        Volume                  totalVolume;
        Weight                  totalWeight;
        SalesLine               salesLine;
        InventTable             inventTable;
        custPackingSlipTrans    custPackingSlipTrans;

        METGrossWeight          metGrossWeight;
        METUnitVolume           metUnitVolume;

        while select salesLine where salesLine.SalesId == _salesId
        {
            metGrossWeight += salesLine.displayMETGrossWeight();
            metUnitVolume += salesLine.displayMETUnitVolume();
        }

        return [metGrossWeight, metUnitVolume];
    }

    private static Qty METGetTotalContainerQty(SalesId _salesId, METWHSContainerChargesMethod _containerChargesMethod)
    {
        METSalesOrderShipmentLoadLines salesOrderShipmentLoadLines;
        MetContainerTable containerTable;
        WHSContainerType containerType;

        select sum(ContainerQty) from containerTable
            exists join containerType
            where containerType.METWHSContainerChargesMethod == _containerChargesMethod
               && containerType.ContainerTypeCode == containerTable.ContainerTypeCode
            exists join salesOrderShipmentLoadLines
            where salesOrderShipmentLoadLines.ShipmentId == containerTable.ShipmentId
               && salesOrderShipmentLoadLines.OrderNum == _salesId;

        return containerTable.ContainerQty;
    }
